            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // soft-deleted owners do not block a create
            }
            if (identity.equals(OwnerIdentity.of(existing))) {
                throw new DuplicateHouseholdException(owner.getHouseholdId());
            }
        }
    }
}

